children.text:
@font-face {
    font-family: 'Programma';
    font-weight: bold;
    src: url('Programma-Bold.woff2') format('woff2');
}
body {
    background-color: linen;
    padding-left: 5%;
    padding-right: 5%;
}
ul {
    list-style: none;
}
ul ul {
    list-style: none;
}
hr {
    background-color: black;
    border: 0px;
    color: black;
    height: 2px;
    padding: 0px;
}
div#box {
    background-color: white;
    border: 2pt solid black;
}
div#grammar {
    padding-top: 1em;
}
div#grammar a:visited {
    color: black;
}
div#spec {
    display: grid;
    gap: 1em;
    grid-template-columns: 1fr max-content;
}
div#text {

}
p.rule {
    font-family: "Open Sans", Futura, "Gill Sans", Arial, Helvetica, sans-serif;
    font-weight: normal;
    margin-left: 4em;
    margin-right: 1em;
    page-break-inside: avoid;
    text-indent: -2em;
    white-space: pre-line;
}
code, pre, tt  {
    font-family: Programma, monospace;
    font-size: 100%;
    font-style: normal;
    font-weight: bold;
}
small {
    font-family: 'Century Schoolbook', serif;
    font-size: 8pt;
    font-style: italic;
    font-weight: normal;
    margin-left: 2pt;
    margin-right: 0.75pt;
}
a {
    text-decoration: none;
}
a:link {
    color: navy;
}
a:visited {
    color: maroon;
}
a:hover {
    color: blue;
    text-decoration: underline;
}
a:active {
    color: red;
}
